def transform(grid):
    h,w=len(grid),len(grid[0]); bg=grid[0][0]
    pts=[(r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x!=bg]
    # object is the connected non-background component with largest extent; zero-valued markers
    # are the scattered placement anchors.
    from collections import deque
    seen=set(); comps=[]
    for p in pts:
        if p in seen: continue
        q=[p]; seen.add(p); comp=[]
        while q:
            r,c=q.pop(); comp.append((r,c))
            for z in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if z in pts and z not in seen: seen.add(z);q.append(z)
        comps.append(comp)
    obj=max(comps,key=len); r0=min(r for r,c in obj);c0=min(c for r,c in obj)
    pat={(r-r0,c-c0):grid[r][c] for r,c in obj}
    out=[row[:] for row in grid]
    # align each singleton marker with the center of the pattern bounding box
    anchors=[comp[0] for comp in comps if len(comp)==1]
    for r,c in anchors:
        for (dr,dc),v in pat.items():
            rr,cc=r+dr-1,c+dc-1
            if 0<=rr<h and 0<=cc<w: out[rr][cc]=v
    return out
